// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Load font at module level to ensure it's ready before rendering
const { fontFamily: playfairFamily } = loadPlayfair();



export type VintageTextAnimationProps = Record<string, any>;

const VintageTextAnimation: React.FC<VintageTextAnimationProps> = ({
  backgroundColor = "#F2EFE9",
  transparentBackground = false,
  durationInSeconds = 10,
  mainText = "pulling up to dinner and going to visit family",
  textColor = "#2C2A26",
  fontSize = 90,
  letterSpacing = 2,
  wordStaggerFrames = 7,
  vignetteOpacity = 0.4,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Parser safety for transparent backgrounds
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  const words = mainText.split(/\s+/).filter(Boolean);
  const totalDurationFrames = fps * durationInSeconds;

  // Slow, cinematic overall camera drift (scale and slight pan)
  const cinematicScale = interpolate(
    frame,
    [0, totalDurationFrames],
    [0.97, 1.05],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: playfairFamily,
        overflow: "hidden",
      }}
    >
      {/* Cinematic Drift Container */}
      <AbsoluteFill
        style={{
          transform: `scale(${cinematicScale})`,
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        {/* Text Container */}
        <div
          style={{
            width: "60%",
            display: "flex",
            flexWrap: "wrap",
            justifyContent: "center",
            alignItems: "center",
            textAlign: "center",
            zIndex: 10,
          }}
        >
          {words.map((word, index) => {
            const startFrame = index * wordStaggerFrames + 10; // Offset start slightly

            // Fade in
            const opacity = interpolate(
              frame,
              [startFrame, startFrame + 30],
              [0, 1],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: Easing.out(Easing.cubic),
              }
            );

            // Subtle rise effect
            const translateY = interpolate(
              frame,
              [startFrame, startFrame + 40],
              [40, 0],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: Easing.out(Easing.bezier(0.2, 0.8, 0.2, 1)),
              }
            );

            // Subtle blur effect using Remotion's blur capabilities
            const blurAmount = interpolate(
              frame,
              [startFrame, startFrame + 25],
              [10, 0],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }
            );

            return (
              <span
                key={`${word}-${index}`}
                style={{
                  color: textColor,
                  fontSize: `${fontSize}px`,
                  fontWeight: 400, // Regular weight for vintage elegance
                  letterSpacing: `${letterSpacing}px`,
                  lineHeight: 1.4,
                  marginRight: "0.3em",
                  marginBottom: "0.2em",
                  opacity,
                  transform: `translateY(${translateY}px)`,
                  filter: `blur(${blurAmount}px)`,
                  transition: "none",
                  display: "inline-block",
                }}
              >
                {word}
              </span>
            );
          })}
        </div>
      </AbsoluteFill>

      {/* Subtle Vignette for Vintage Film Look */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle, transparent 40%, rgba(0, 0, 0, ${vignetteOpacity}) 150%)`,
          pointerEvents: "none",
          mixBlendMode: "multiply",
          zIndex: 20,
        }}
      />
    </AbsoluteFill>
  );
};

export default VintageTextAnimation;